class Sensor {
public:
    virtual float read() = 0;  // pure virtual — контракт
    virtual ~Sensor() = default;
};

class TemperatureSensor : public Sensor {
public:
    float read() override { return readADC(TEMP_PIN); }
};

class PressureSensor : public Sensor {
public:
    float read() override { return readADC(PRESS_PIN); }
};

void logSensor(Sensor& s) {  // работает с Sensor*, не зная конкретный датчик
    printf("value: %f\n", s.read());
}
